const p = new Promise((resolve, reject) => {
  resolve("pertama");
  resolve("kedua");
  reject(new Error("gagal"));
  console.log("kode setelah resolve tetap berjalan");
});
p.then((v) => console.log("hasil:", v)).catch((e) => console.log("error:", e.message));

